import java.util.*;
import java.io.*;

public class E1342_Variant1 {

    static long mod = 998244353;

    static long modPow(long base, long exp) {
        base %= mod;
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long[] factorial, invFactorial;

    public static long nChooseK(long n, long k) {
        return factorial[(int) n] * invFactorial[(int) k] % mod * invFactorial[(int) (n - k)] % mod;
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        long n = scanner.nextInt();
        long k = scanner.nextLong();

        if (k >= n) {
            writer.println(0);
            writer.close();
            return;
        }

        factorial = new long[(int) n + 1];
        invFactorial = new long[(int) n + 1];

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (i * factorial[i - 1]) % mod;
        }

        invFactorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            invFactorial[i] = (invFactorial[i - 1] * modPow(i, mod - 2)) % mod;
        }

        long m = n - k;
        long positiveSum = 0;
        long negativeSum = 0;

        for (int i = 0; i <= m; i++) {
            long term = (modPow(m - i, n) * nChooseK(m, i)) % mod;
            if (i % 2 == 0) {
                positiveSum = (positiveSum + term) % mod;
            } else {
                negativeSum = (negativeSum + term) % mod;
            }
        }

        long answer = (positiveSum - negativeSum + 2 * mod) % mod;
        answer = (answer * nChooseK(n, m)) % mod;

        if (m != n) {
            answer = (answer * 2) % mod;
        }

        writer.println(answer);
        writer.close();
    }
}
